use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** Initialize EntryPointContract
  *
  * guarantee INITIAL_REQUEST_HISTORY
  * @param previousOff post-state state variable
  * @param previousReturn post-state state variable
  * @param previousStart post-state state variable
  * @param api_request_to_authorization outgoing data port
  * @param api_request_to_lifecycle outgoing data port
  */
pub fn initialize_INITIAL_REQUEST_HISTORY(
  previousOff: bool,
  previousReturn: bool,
  previousStart: bool,
  api_request_to_authorization: Vehicle_Start_Readiness_Recovery_Supervisor::RequestFacts,
  api_request_to_lifecycle: Vehicle_Start_Readiness_Recovery_Supervisor::RequestFacts) -> bool
{
  (previousStart == false) &
    (previousOff == false) &
    (previousReturn == false) &
    (api_request_to_authorization.offActive == false) &
    (api_request_to_authorization.freshReturn == false) &
    (api_request_to_authorization.freshStart == false) &
    (api_request_to_authorization.conflict == false) &
    (api_request_to_authorization.disposition == Vehicle_Start_Readiness_Recovery_Supervisor::RequestDisposition::None) &
    (api_request_to_lifecycle.offActive == false) &
    (api_request_to_lifecycle.freshReturn == false) &
    (api_request_to_lifecycle.freshStart == false) &
    (api_request_to_lifecycle.conflict == false) &
    (api_request_to_lifecycle.disposition == Vehicle_Start_Readiness_Recovery_Supervisor::RequestDisposition::None)
}

